from itertools import product


def _mode_line(grid, axis, index):
    values = grid[index] if axis == 0 else [row[index] for row in grid]
    color, count = Counter(values).most_common(1)[0]
    return color, count / len(values)


def _axis_progressions(grid, axis, rail_color):
    n = len(grid) if axis == 0 else len(grid[0])
    qualified = {i for i in range(n)
                 if (lambda z: z[0] == rail_color and z[1] >= 0.62)(_mode_line(grid, axis, i))}
    found = []
    for step in range(2, n):
        for start in range(n):
            seq = list(range(start, n, step))
            if len(seq) >= 2 and all(i in qualified for i in seq):
                found.append(tuple(seq))
    return list(dict.fromkeys(found))


def _uniform_ratio(grid, r0, r1, c0, c1):
    cells = [grid[r][c] for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)]
    if not cells:
        return 0.0, None
    color, count = Counter(cells).most_common(1)[0]
    return count / len(cells), color


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the regularly spaced, nearly uniform row/column rails whose enclosed
    # panels are themselves uniform. The values at rail crossings are symbols.
    best = None
    for rail in set(v for row in grid for v in row):
        row_seqs = _axis_progressions(grid, 0, rail)
        col_seqs = _axis_progressions(grid, 1, rail)
        for rs, cs in product(row_seqs, col_seqs):
            ratios, panel_colors = [], []
            for r0, r1 in zip(rs, rs[1:]):
                for c0, c1 in zip(cs, cs[1:]):
                    ratio, color = _uniform_ratio(grid, r0, r1, c0, c1)
                    ratios.append(ratio)
                    panel_colors.append(color)
            if not ratios:
                continue
            line_quality = sum(_mode_line(grid, 0, r)[1] for r in rs) / len(rs)
            line_quality += sum(_mode_line(grid, 1, c)[1] for c in cs) / len(cs)
            panel_quality = sum(ratios) / len(ratios)
            # Favor genuinely regular rails and homogeneous enclosed panels;
            # prefer larger supported lattices when quality ties.
            score = (panel_quality, line_quality, len(rs) * len(cs), -rail)
            if best is None or score > best[0]:
                best = (score, rail, rs, cs, panel_colors)
    if best is None:
        return [row[:] for row in grid]

    _, rail, rs, cs, panel_colors = best
    nr, nc = len(rs) - 1, len(cs) - 1
    out = [[None] * nc for _ in range(nr)]
    for i, (r0, r1) in enumerate(zip(rs, rs[1:])):
        for j, (c0, c1) in enumerate(zip(cs, cs[1:])):
            markers = {grid[r][c] for r in (r0, r1) for c in (c0, c1) if grid[r][c] != rail}
            base = panel_colors[i * nc + j]
            out[i][j] = next(iter(markers)) if len(markers) == 1 else base

    # The examples encode a compact answer: discard outer intervals that have
    # no non-rail crossing symbols at either endpoint.
    active = [(r, c) for r in range(len(rs)) for c in range(len(cs))
              if grid[rs[r]][cs[c]] != rail]
    if active:
        rlo = min(r for r, _ in active)
        rhi = max(r for r, _ in active)
        clo = min(c for _, c in active)
        chi = max(c for _, c in active)
        out = [row[clo:chi] for row in out[rlo:rhi]]
    return out


