def _line_color(grid, axis, i):
    line = grid[i] if axis == 0 else [row[i] for row in grid]
    color, count = Counter(line).most_common(1)[0]
    return color, count / len(line)


def _uniform_inner(grid, r0, r1, c0, c1):
    cells = [grid[r][c] for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)]
    if not cells:
        return None, 0.0
    color, count = Counter(cells).most_common(1)[0]
    return color, count / len(cells)


def _single_framed_symbol(grid):
    h, w = len(grid), len(grid[0])
    best = None
    colors = {v for row in grid for v in row}
    for rail in colors:
        rows = [r for r in range(h) if _line_color(grid, 0, r)[0] == rail and _line_color(grid, 0, r)[1] >= .65]
        cols = [c for c in range(w) if _line_color(grid, 1, c)[0] == rail and _line_color(grid, 1, c)[1] >= .65]
        for r0, r1 in combinations(rows, 2):
            for c0, c1 in combinations(cols, 2):
                corners = [grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1]]
                markers = set(corners) - {rail}
                if len(markers) != 1:
                    continue
                inside, purity = _uniform_inner(grid, r0, r1, c0, c1)
                marker = next(iter(markers))
                if inside in (None, rail, marker) or purity < .9:
                    continue
                # A candidate frame must not simply be two unrelated stripes:
                # its interior is a uniform field, and all four corners agree.
                score = (purity, (r1-r0)*(c1-c0), -rail)
                if best is None or score > best[0]:
                    best = (score, marker)
    return [[best[1]]] if best else None


def transform(grid):
    # A rectangular lattice enclosing one uniform field and four matching
    # corner symbols reduces to that symbol. This covers the 1x1 frames in the
    # demonstrations and the current test.
    framed = _single_framed_symbol(grid)
    if framed is not None:
        return framed

    # For larger lattices, reduce each interval rectangle to its uniform
    # interior color. Non-rail symbols at the four crossings override a panel
    # only when all four corners agree.
    h, w = len(grid), len(grid[0])
    best = None
    for rail in {v for row in grid for v in row}:
        rows = [r for r in range(h) if _line_color(grid, 0, r)[0] == rail and _line_color(grid, 0, r)[1] >= .62]
        cols = [c for c in range(w) if _line_color(grid, 1, c)[0] == rail and _line_color(grid, 1, c)[1] >= .62]
        if len(rows) < 2 or len(cols) < 2:
            continue
        # Keep the full progression with constant spacing, excluding spurious
        # subsets; choose the most complete regular lattice.
        for dr in range(1, h):
            rs = [r for r in rows if (r - rows[0]) % dr == 0]
            if len(rs) < 2:
                continue
            for dc in range(1, w):
                cs = [c for c in cols if (c - cols[0]) % dc == 0]
                if len(cs) < 2:
                    continue
                if any(b-a != dr for a,b in zip(rs,rs[1:])) or any(b-a != dc for a,b in zip(cs,cs[1:])):
                    continue
                panels, purities = [], []
                for r0,r1 in zip(rs,rs[1:]):
                    row=[]
                    for c0,c1 in zip(cs,cs[1:]):
                        interior,purity=_uniform_inner(grid,r0,r1,c0,c1)
                        corners=[grid[r0][c0],grid[r0][c1],grid[r1][c0],grid[r1][c1]]
                        nonrail=set(corners)-{rail}
                        row.append(next(iter(nonrail)) if len(nonrail)==1 and all(x in nonrail for x in corners) else interior)
                        purities.append(purity)
                    panels.append(row)
                score=(len(rs)*len(cs),sum(purities)/len(purities),-rail)
                if best is None or score>best[0]: best=(score,panels)
    if best:
        return best[1]
    return [row[:] for row in grid]


