    test = [[5]*28 for _ in range(12)]
    for c in range(28): test[1][c]=0; test[8][c]=0
    for r in range(12): test[r][1]=0; test[r][27]=0
    for r,c in ((1,1),(1,27),(8,1),(8,27)): test[r][c]=2
    result=transform(test)
