    """Reduce a uniform rectangular field bounded by matching corner markers."""
    h, w = len(grid), len(grid[0])
    for r0 in range(h):
        for r1 in range(r0 + 2, h):
            for c0 in range(w):
                for c1 in range(c0 + 2, w):
                    corners = (grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1])
                    marker = corners[0]
                    if marker == 0 or any(v != marker for v in corners):
                        continue
                    inner = [grid[r][c] for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)]
                    if not inner:
                        continue
                    fill, count = Counter(inner).most_common(1)[0]
                    if count / len(inner) < .95 or fill == marker:
